// =====================================================================
// BocBox - SCRIPT TỔNG cho MongoDB: xóa database bocbox rồi tạo lại collection, index và toàn bộ dữ liệu mẫu.
// Chạy lại bất cứ lúc nào để về trạng thái ban đầu (MẤT HẾT dữ liệu đang có trong database bocbox).
//
// Cách chạy:
//   MongoDB Atlas: mongosh "mongodb+srv://<user>:<mật khẩu>@<cluster>.mongodb.net/" --file backend/db/bocbox-full.mongodb.js
//                  (hoặc mở MongoDB Compass → tab MONGOSH → dán cả file → Enter)
//   docker-compose: tự chạy lần đầu (file được gắn vào /docker-entrypoint-initdb.d).
//
// Tài khoản quản trị: admin / Bocbox@2026 và nhanvien / Bocbox@2026.
// Tài khoản khách mẫu: 0901000001 … 0901000024, mật khẩu Bocbox@2026.
// Id dạng số (NumberLong) như bản SQL cũ; collection "counters" giữ số id tiếp theo cho backend.
// Ngày giờ tính theo thứ Hai của tuần chạy script (giờ Việt Nam), nên đợt cuối luôn là đợt đang mở.
// =====================================================================
const DB_NAME = 'bocbox';   // phải trùng tên database trong MONGODB_URI của backend
const target = db.getSiblingDB(DB_NAME);
target.dropDatabase();

// --- thời gian: lưu Date (UTC) ứng với giờ Việt Nam ---
// Chỉ dùng phép tính trên số mili-giây (không dùng Date.UTC / getUTC*), để chạy được cả trong console
// MongoDB của IntelliJ / DataGrip (mongosh nhúng không có đủ hàm Date) lẫn mongosh / Compass.
const VN = 7 * 3600 * 1000, MIN = 60 * 1000, DAY = 24 * 3600 * 1000;
const nowMs = new Date().getTime();
const dayOf = (vnMs) => Math.floor(vnMs / DAY);                // số ngày kể từ 01/01/1970 (giờ VN)
const weekday = (dn) => ((dn + 3) % 7 + 7) % 7;                 // 0 = thứ Hai (01/01/1970 là thứ Năm)
const monVn = (dayOf(nowMs + VN) - weekday(dayOf(nowMs + VN))) * DAY;
const at = (vnMs) => new Date(vnMs - VN);                       // giờ VN (dạng số) → Date thật
const pad = (n) => String(n).padStart(2, '0');
function civil(dn) {                                            // số ngày → [năm, tháng, ngày] (thuật toán Hinnant)
  const z = dn + 719468, era = Math.floor(z / 146097), doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100)), mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1, m = mp < 10 ? mp + 3 : mp - 9;
  return [yoe + era * 400 + (m <= 2 ? 1 : 0), m, d];
}
function daysFromCivil(y, m, d) {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400), yoe = y - era * 400, mp = (m + 9) % 12;
  const doy = Math.floor((153 * mp + 2) / 5) + d - 1, doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}
const yymmdd = (vnMs) => { const [y, m, d] = civil(dayOf(vnMs)); return pad(y % 100) + pad(m) + pad(d); };
function isoWeek(vnMs) {                                        // tuần ISO (giống WeekFields.ISO của Java)
  const dn = dayOf(vnMs), thu = dn - weekday(dn) + 3;
  return Math.floor((thu - daysFromCivil(civil(thu)[0], 1, 1)) / 7) + 1;
}
const now = new Date(nowMs);

