// 8. Đợt pre-order: 4 tuần trước + tuần hiện tại (đang mở). Mở thứ Hai 00:00, đóng Chủ nhật 23:59:59, giao thứ Năm–Sáu tuần sau.
const BATCH_WEEKS = [[1, -4, "SHIPPED"], [2, -3, "SHIPPED"], [3, -2, "SHIPPED"], [4, -1, "PRINTING"], [5, 0, "OPEN"]];  // [id, tuần so với tuần này, trạng thái]
const batchOpen = {};
target.batches.insertMany(BATCH_WEEKS.map(([id, wk, status]) => {
  const open = monVn + wk * 7 * DAY; batchOpen[id] = open;
  return { _id: NumberLong(id), code: 'W' + pad(civil(dayOf(open))[0] % 100) + pad(isoWeek(open)),
           openAt: at(open), closeAt: at(open + 7 * DAY - 1000), deliveryFrom: at(open + 10 * DAY), deliveryTo: at(open + 11 * DAY), status };
}));

